use std::ffi::CString;
use std::ptr::null_mut;
use ndk_sys::{
    AMediaCodec, AMediaFormat, AMediaFormat_new, AMediaFormat_delete,
        AMediaFormat_setString, AMediaFormat_setInt32, AMediaFormat_setFloat,
            AMediaCodec_createEncoderByType, AMediaCodec_configure,
                AMediaCodec_createInputSurface, AMediaCodec_start, ANativeWindow
                };

                /// Rate-control modes matching Android MediaCodec BITRATE_MODE specifications.
                #[repr(i32)]
                #[derive(Debug, Clone, Copy)]
                pub enum BitrateMode {
                    /// Constant Quality (CQ) - Matches FFmpeg CRF/CQP target
                        Cq = 0,
                            /// Variable Bitrate (VBR) - Codec decides instantaneous bit allocation
                                Vbr = 1,
                                    /// Constant Bitrate (CBR) - Strictly stays near target bitrate
                                        Cbr = 2,
                                            /// Constant Bitrate with Frame Drops (CBR_FD) - API 31+
                                                CbrFd = 3,
                                                }

                                                pub struct VideoEncoderParameters {
                                                    pub mime_type: String,
                                                        pub width: i32,
                                                            pub height: i32,
                                                                pub frame_rate: i32,
                                                                    pub bit_rate: i32,
                                                                        pub bitrate_mode: BitrateMode,
                                                                            /// Equivalent to FFmpeg -g parameter (Key-frame / GOP distance in seconds)
                                                                                pub i_frame_interval_seconds: i32,
                                                                                    pub profile: Option<i32>,
                                                                                        pub level: Option<i32>,
                                                                                            /// Low latency execution preference (if supported by chipset)
                                                                                                pub low_latency_enabled: bool,
                                                                                                }

                                                                                                pub struct AdvancedVideoEncoder {
                                                                                                    codec_handle: *mut AMediaCodec,
                                                                                                        input_window: *mut ANativeWindow,
                                                                                                        }

                                                                                                        impl AdvancedVideoEncoder {
                                                                                                            /// Configures the hardware video encoder with deep low-level parameters.
                                                                                                                pub fn create(params: &VideoEncoderParameters) -> Result<Self, String> {
                                                                                                                        unsafe {
                                                                                                                                    let mime_c = CString::new(params.mime_type.as_str()).map_err(|e| e.to_string())?;
                                                                                                                                                let codec = AMediaCodec_createEncoderByType(mime_c.as_ptr());
                                                                                                                                                            if codec.is_null() {
                                                                                                                                                                            return Err("Requested hardware encoder type not found on device".to_string());
                                                                                                                                                                                        }

                                                                                                                                                                                                    let format = AMediaFormat_new();
                                                                                                                                                                                                                if format.is_null() {
                                                                                                                                                                                                                                ndk_sys::AMediaCodec_delete(codec);
                                                                                                                                                                                                                                                return Err("Failed to allocate native AMediaFormat".to_string());
                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                        // Standard dimensions & timing
                                                                                                                                                                                                                                                                                    AMediaFormat_setString(format, ndk_sys::AMEDIAFORMAT_KEY_MIME, mime_c.as_ptr());
                                                                                                                                                                                                                                                                                                AMediaFormat_setInt32(format, ndk_sys::AMEDIAFORMAT_KEY_WIDTH, params.width);
                                                                                                                                                                                                                                                                                                            AMediaFormat_setInt32(format, ndk_sys::AMEDIAFORMAT_KEY_HEIGHT, params.height);
                                                                                                                                                                                                                                                                                                                        AMediaFormat_setInt32(format, ndk_sys::AMEDIAFORMAT_KEY_FRAME_RATE, params.frame_rate);
                                                                                                                                                                                                                                                                                                                                    AMediaFormat_setInt32(format, ndk_sys::AMEDIAFORMAT_KEY_BIT_RATE, params.bit_rate);

                                                                                                                                                                                                                                                                                                                                                // Rate-control mapping (-bitrate_mode)
                                                                                                                                                                                                                                                                                                                                                            let bitrate_mode_key = CString::new("bitrate-mode").unwrap();
                                                                                                                                                                                                                                                                                                                                                                        AMediaFormat_setInt32(format, bitrate_mode_key.as_ptr(), params.bitrate_mode as i32);

                                                                                                                                                                                                                                                                                                                                                                                    // GOP mapping (-g interval in seconds)
                                                                                                                                                                                                                                                                                                                                                                                                AMediaFormat_setInt32(
                                                                                                                                                                                                                                                                                                                                                                                                                format,
                                                                                                                                                                                                                                                                                                                                                                                                                                ndk_sys::AMEDIAFORMAT_KEY_I_FRAME_INTERVAL,
                                                                                                                                                                                                                                                                                                                                                                                                                                                params.i_frame_interval_seconds,
                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // COLOR_FormatSurface (0x7F000789) -> Direct GPU texture intake
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    AMediaFormat_setInt32(format, ndk_sys::AMEDIAFORMAT_KEY_COLOR_FORMAT, 0x7F000789);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Optional profile and tier mappings (e.g., High, Baseline, Main)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if let Some(prof) = params.profile {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let profile_key = CString::new("profile").unwrap();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            AMediaFormat_setInt32(format, profile_key.as_ptr(), prof);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if let Some(lvl) = params.level {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    let level_key = CString::new("level").unwrap();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    AMediaFormat_setInt32(format, level_key.as_ptr(), lvl);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Low-latency mode toggle (Android Q+)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if params.low_latency_enabled {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let latency_key = CString::new("latency").unwrap();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AMediaFormat_setInt32(format, latency_key.as_ptr(), 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let config_res = AMediaCodec_configure(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                codec,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                format,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                null_mut(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                null_mut(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ndk_sys::AMEDIACODEC_CONFIGURE_FLAG_ENCODE as u32,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AMediaFormat_delete(format);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if config_res != 0 {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ndk_sys::AMediaCodec_delete(codec);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return Err(format!("MediaCodec configure returned error code: {}", config_res));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Zero-copy hardware ingestion surface setup
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let mut native_window: *mut ANativeWindow = null_mut();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    let surface_res = AMediaCodec_createInputSurface(codec, &mut native_window);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if surface_res != 0 || native_window.is_null() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ndk_sys::AMediaCodec_delete(codec);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return Err("Failed to generate zero-copy hardware input surface".to_string());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let start_res = AMediaCodec_start(codec);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if start_res != 0 {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ndk_sys::AMediaCodec_delete(codec);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return Err(format!("MediaCodec start failed with code: {}", start_res));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Ok(Self {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            codec_handle: codec,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            input_window: native_window,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pub fn get_surface_handle(&self) -> *mut ANativeWindow {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                self.input_window
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }